 void conversations(){if(busy){toast("请等待本次回答完成");return;}LinearLayout list=column();list.setPadding(dp(16),0,dp(16),0);EditText search=field(list,"按主题或聊天内容搜索","");LinearLayout results=column();ScrollView scroll=new ScrollView(this);scroll.addView(results);list.addView(scroll,new LinearLayout.LayoutParams(-1,dp(370)));AlertDialog dialog=new UiDialog.Builder(this).setTitle("历史会话 · 按最近时间").setView(list).setPositiveButton("新对话",(d,w)->{session=db.create("新对话","日常");limit=50;draft="";chatInput=null;attached=new JSONArray();status="新对话";prefs.edit().putString("currentChat",session).apply();render();}).setNegativeButton("关闭",null).create();Runnable show=()->{results.removeAllViews();JSONArray sessions=db.sessions(search.getText().toString());for(int i=0;i<sessions.length();i++){JSONObject s=sessions.optJSONObject(i);String label=s.optString("title")+"\n"+s.optString("topic")+" · "+Instant.ofEpochMilli(s.optLong("updated")).atZone(Schedule.ZONE).toLocalDate();Button b=button(label,()->{session=s.optString("id");limit=50;prefs.edit().putString("currentChat",session).apply();dialog.dismiss();render();});b.setOnLongClickListener(v->{LinearLayout form=column();EditText title=field(form,"会话名称",s.optString("title")),topic=field(form,"主题",s.optString("topic"));new UiDialog.Builder(this).setTitle("编辑会话分类").setView(form).setPositiveButton("保存",(a,x)->{db.rename(s.optString("id"),title.getText().toString(),topic.getText().toString());dialog.dismiss();conversations();}).setNegativeButton("取消",null).show();return true;});results.addView(b);}};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){show.run();}public void afterTextChanged(android.text.Editable e){}});show.run();dialog.show();}
 void menu(){String[] items={"个人记忆与习惯","切换模型","附带日程："+(prefs.getBoolean("aiContext",true)?"开":"关"),"配置 DeepSeek Key","导出聊天和记忆备份","导入聊天和记忆备份","回到日程设置","撤销最近一次助手任务操作","思考强度："+ThinkingMode.label(prefs.getString("thinking","none")),"查看本次使用的习惯提示词","历史会话"};new UiDialog.Builder(this).setItems(items,(d,w)->{if(w==10)conversations();if(w==0)learnedMemory();if(w==1)modelDialog();if(w==2){prefs.edit().putBoolean("aiContext",!prefs.getBoolean("aiContext",true)).apply();render();}if(w==3)secretDialog("deepseek","DeepSeek API Key");if(w==4){if(busy||importing){toast("请等待当前操作完成");return;}exportKind="backup";createDocument("application/zip","saber喵聊天记忆-"+LocalDate.now()+".zip");}if(w==5){if(busy||importing){toast("请等待当前操作完成");return;}startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("application/zip").addCategory(Intent.CATEGORY_OPENABLE),204);}if(w==6)startActivity(new Intent(this,MainActivity.class).putExtra("page","settings"));if(w==8)thinkingDialog();if(w==9)new UiDialog.Builder(this).setTitle("习惯提示词 · 最多500字").setMessage(MemoryRecall.compact(learned(),chatInput==null?"":chatInput.getText().toString(),500)+"\n\n新对话不会发送其他会话全文。记录依据在个人记忆页查看。").setPositiveButton("关闭",null).show();if(w==7){synchronized(TaskStore.class){String expected=prefs.getString("undoTasksAfter","");if(expected.isEmpty()||!TaskStore.load(this).toString().equals(expected)){toast("事项已发生其他变化，无法整批撤销；可以直接告诉助手如何改回");return;}try{TaskStore.save(this,new JSONArray(prefs.getString("undoTasksBefore","[]")));prefs.edit().remove("undoTasksAfter").remove("undoTasksBefore").apply();toast("已撤销最近一次助手任务操作");}catch(Exception e){toast("撤销失败");}}}}).show();}
 void thinkingDialog(){String[] values={"none","low","high","max"};String selected=prefs.getString("thinking","none");int checked=0;for(int i=0;i<values.length;i++)if(values[i].equals(selected))checked=i;new UiDialog.Builder(this).setTitle("思考强度 · 越深通常越慢").setSingleChoiceItems(new String[]{"快速 · 关闭推理，日常问答/改日程","轻度 · 少量推理，一般分析","深入 · 更充分推理，复杂规划","最高 · 最大推理力度，用量可能明显增加"},checked,(d,w)->{prefs.edit().putString("thinking",values[w]).apply();d.dismiss();render();}).setNegativeButton("关闭",null).show();}
