 void replyActions(String raw){String plain=LearnedMemory.visible(raw);String[] choices={"复制回答","保存 Markdown","保存 TXT","保存 PDF","保存回答长图 PNG","保存代码块 / CSV / JSON 文件","从回答创建待办","预览备注修改","保存 PPT"};new UiDialog.Builder(this).setItems(choices,(d,w)->{if(w==0){getSystemService(android.content.ClipboardManager.class).setPrimaryClip(ClipData.newPlainText("saber喵回答",plain));toast("已复制");}else if(w>=1&&w<=4){exportText=plain;exportKind=new String[]{"","md","txt","pdf","png"}[w];createDocument(w==3?"application/pdf":w==4?"image/png":"text/plain","saber喵回答-"+LocalDate.now()+"."+exportKind);}else if(w==5){java.util.regex.Matcher m=java.util.regex.Pattern.compile("```(csv|json|ics|txt|md|java|python|py|c)\\s*\\n([\\s\\S]*?)```").matcher(raw);if(!m.find()){toast("没有可导出的代码块，可让助手生成 CSV、JSON 等格式");return;}exportKind="text";exportText=m.group(2);createDocument("text/plain","saber喵生成文件."+(m.group(1).equals("python")?"py":m.group(1)));}else if(w==6){JSONObject p=TaskProposal.parse(raw);if(p.length()==0)toast("回答中没有待办草稿，请让助手创建一件事项");else edit(null,p);}else if(w==7)previewNote(raw);else if(w==8){exportText=plain;exportKind="pptx";createDocument("application/vnd.openxmlformats-officedocument.presentationml.presentation","saber喵演示文稿-"+LocalDate.now()+".pptx");}}).show();}
